sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var message = '';

    if (newValue.toLowerCase() === 'excellent') {
        message = "Thank you for your excellent feedback!";
    } else if (newValue.toLowerCase() === 'good') {
        message = "Thanks! We're glad you had a good experience.";
    } else if (newValue.toLowerCase() === 'average') {
        message = "Thanks for your feedback. We'll keep working to improve.";
    } else if (newValue.toLowerCase() === 'poor') {
        message = "We're sorry to hear that. Your feedback helps us do better.";
    } else {
        message = "Thank you for your feedback.";
    }

    // Show message below the rating field
    g_form.showFieldMsg('u_rating', message, 'info');
}
